<?php
require_once __DIR__.'/../config/app.php';require_once __DIR__.'/../config/koneksi.php';require_admin();$pageTitle='Penempatan PKL';$errors=[];
if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();$a=$_POST['action']??'';$id=(int)($_POST['id']??0);if($a==='delete'){$pdo->prepare("DELETE FROM penempatan WHERE id=?")->execute([$id]);flash('success','Penempatan dihapus.');redirect('penempatan.php');}
 $sid=(int)($_POST['siswa_id']??0);$pid=(int)($_POST['perusahaan_id']??0);$bid=(int)($_POST['pembimbing_id']??0);$mulai=$_POST['tanggal_mulai']??'';$selesai=$_POST['tanggal_selesai']??'';$status=$_POST['status']??'Belum Mulai';
 if(!$sid||!$pid||!$bid||!$mulai||!$selesai)$errors[]='Semua data penempatan wajib dilengkapi.';if($mulai&&$selesai&&$selesai<$mulai)$errors[]='Tanggal selesai tidak boleh sebelum tanggal mulai.';
 $q=$pdo->prepare("SELECT id FROM penempatan WHERE siswa_id=? AND id<>? AND status<>'Selesai'");$q->execute([$sid,$id]);if($q->fetch())$errors[]='Siswa masih memiliki penempatan aktif.';
 if(!$errors){if($a==='create')$q=$pdo->prepare("INSERT INTO penempatan(siswa_id,perusahaan_id,pembimbing_id,tanggal_mulai,tanggal_selesai,status) VALUES(?,?,?,?,?,?)");else $q=$pdo->prepare("UPDATE penempatan SET siswa_id=?,perusahaan_id=?,pembimbing_id=?,tanggal_mulai=?,tanggal_selesai=?,status=? WHERE id=?");$a==='create'?$q->execute([$sid,$pid,$bid,$mulai,$selesai,$status]):$q->execute([$sid,$pid,$bid,$mulai,$selesai,$status,$id]);flash('success','Penempatan berhasil disimpan.');redirect('penempatan.php');}}
$edit=null;if(isset($_GET['edit'])){$q=$pdo->prepare("SELECT * FROM penempatan WHERE id=?");$q->execute([(int)$_GET['edit']]);$edit=$q->fetch();}
$students=$pdo->query("SELECT id,nis,nama FROM siswa ORDER BY nama")->fetchAll();$companies=$pdo->query("SELECT id,nama FROM perusahaan ORDER BY nama")->fetchAll();$mentors=$pdo->query("SELECT id,nama FROM pembimbing ORDER BY nama")->fetchAll();
$filter=trim($_GET['status']??'');$sql="SELECT p.*,s.nama siswa,pr.nama perusahaan,b.nama pembimbing FROM penempatan p JOIN siswa s ON s.id=p.siswa_id JOIN perusahaan pr ON pr.id=p.perusahaan_id JOIN pembimbing b ON b.id=p.pembimbing_id WHERE 1";$params=[];if($filter!==''){$sql.=" AND p.status=?";$params[]=$filter;}$sql.=" ORDER BY p.id DESC";$q=$pdo->prepare($sql);$q->execute($params);$rows=$q->fetchAll();include __DIR__.'/../partials/header.php';?>
<div class="page-head"><div><h1>Penempatan PKL</h1><div class="muted">Hubungkan siswa, perusahaan, dan pembimbing.</div></div></div><?php foreach($errors as $x):?><div class="alert danger"><?=e($x)?></div><?php endforeach;?>
<div class="card"><h3><?=$edit?'Edit Penempatan':'Tambah Penempatan'?></h3><form method="post"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="<?=$edit?'update':'create'?>"><input type="hidden" name="id" value="<?=e($edit['id']??'')?>"><div class="form-grid">
<div class="field"><label>Siswa *</label><select name="siswa_id" required><option value="">Pilih siswa</option><?php foreach($students as $x):?><option value="<?=$x['id']?>" <?=($edit['siswa_id']??'')==$x['id']?'selected':''?>><?=e($x['nis'].' - '.$x['nama'])?></option><?php endforeach;?></select></div>
<div class="field"><label>Perusahaan *</label><select name="perusahaan_id" required><option value="">Pilih perusahaan</option><?php foreach($companies as $x):?><option value="<?=$x['id']?>" <?=($edit['perusahaan_id']??'')==$x['id']?'selected':''?>><?=e($x['nama'])?></option><?php endforeach;?></select></div>
<div class="field"><label>Pembimbing *</label><select name="pembimbing_id" required><option value="">Pilih pembimbing</option><?php foreach($mentors as $x):?><option value="<?=$x['id']?>" <?=($edit['pembimbing_id']??'')==$x['id']?'selected':''?>><?=e($x['nama'])?></option><?php endforeach;?></select></div>
<div class="field"><label>Status</label><select name="status"><?php foreach(['Belum Mulai','Aktif','Selesai'] as $st):?><option <?=($edit['status']??'Belum Mulai')===$st?'selected':''?>><?=e($st)?></option><?php endforeach;?></select></div>
<div class="field"><label>Tanggal Mulai *</label><input type="date" name="tanggal_mulai" required value="<?=e($edit['tanggal_mulai']??'')?>"></div><div class="field"><label>Tanggal Selesai *</label><input type="date" name="tanggal_selesai" required value="<?=e($edit['tanggal_selesai']??'')?>"></div></div><div class="form-actions"><button class="btn">Simpan Penempatan</button><?php if($edit):?><a class="btn secondary" href="penempatan.php">Batal</a><?php endif;?></div></form></div>
<div class="card"><form class="filters"><select name="status"><option value="">Semua status</option><?php foreach(['Belum Mulai','Aktif','Selesai'] as $st):?><option <?= $filter===$st?'selected':''?>><?=e($st)?></option><?php endforeach;?></select><button class="btn">Filter</button></form><div class="table-wrap"><table><thead><tr><th>Siswa</th><th>Perusahaan</th><th>Pembimbing</th><th>Periode</th><th>Status</th><th>Aksi</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['siswa'])?></td><td><?=e($r['perusahaan'])?></td><td><?=e($r['pembimbing'])?></td><td><?=e($r['tanggal_mulai'])?> – <?=e($r['tanggal_selesai'])?></td><td><span class="badge <?= $r['status']==='Aktif'?'success':($r['status']==='Selesai'?'':'warning')?>"><?=e($r['status'])?></span></td><td><div class="actions"><a class="btn secondary small" href="?edit=<?=$r['id']?>">Edit</a><form method="post" data-confirm="Hapus penempatan ini?"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=$r['id']?>"><button class="btn danger small">Hapus</button></form></div></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="6" class="empty">Belum ada penempatan. Isi data siswa, perusahaan, dan pembimbing terlebih dahulu.</td></tr><?php endif;?></tbody></table></div></div><?php include __DIR__.'/../partials/footer.php';?>
